import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.egate.generictabcontent import GenericTabContent

__author__ = "Bartlomiej 1. Kopacz"
__copyright__ = "Copyright (C) 2019, Nokia"
__email__ = "bartlomiej.1.kopacz@nokia.com"


class SeqDel(GenericTabContent):
    """Seqdel command class."""

    def __init__(self, connection, seq_id, prompt=None, newline_chars=None, runner=None):
        """
        Seqdel command.

        :param connection: moler connection to device, terminal when command is executed.
        :param seq_id: Command sequence identifier, accept values 1-1024, required
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SeqDel, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.seq_id = seq_id

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "seq_del"
        if self.seq_id:
            cmd = f"{cmd} id={self.seq_id}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_deleted(line)
            except ParsingDone:
                pass
        return super(SeqDel, self).on_new_line(line, is_full_line)

    # Command Sequence 101 is deleted.
    _re_deleted = re.compile(r".*Sequence (?P<SEQ_ID>.*) is deleted")

    def _parse_deleted(self, line):
        if self._regex_helper.search_compiled(SeqDel._re_deleted, line):
            seq_id = self._regex_helper.group("SEQ_ID")
            self.current_ret["id"] = int(seq_id)
            raise ParsingDone


COMMAND_OUTPUT = """EGATE> seq_del id=101
Command Sequence 101 is deleted.

EGATE>"""

